"""Fail-closed scope/integrity checks; geometry evidence is generated by FreeCAD."""
import json
import unittest
from pathlib import Path
from release_check import verify

ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'hardware/cad/studies/whole-cat-packaging/cp2/open-prototype/wiring-checkpoint'


def read(name):
    return json.loads((OUT/name).read_text())


def test_current_package_integrity():
    assert verify(ROOT,read('source-retention-package.json'))['integrity_ok']


def test_not_print_ready_or_whole_wiring_complete():
    package=read('source-retention-package.json')
    assert not verify(ROOT,package,True)['integrity_ok']
    assert not any(package[k] for k in ('selected','physical_pass','stage_completed','source_retention_checkpoint_complete'))
    assert package['minimum_confirmed_results']=='3/20=15%,unchanged'


def test_changed_S1_scope_and_parameter_restore():
    proof=read('source-retention-checks.json')
    assert not proof['contacts'] and not proof['errors']
    assert proof['parameter_mm']==[3,3.5,3] and proof['parameter_restored']
    assert proof['candidate_hardware']=={'M3x8':2,'M3_washer':2,'M3_nut':2}


def test_existing_dependencies_are_not_waived():
    proof=read('source-retention-checks.json');reopen=read('source-retention-reopen.json')
    assert proof['unresolved_prior_carrier_interfaces']
    assert reopen['unresolved_D_RL_column_contacts']
    assert reopen['obsolete_MTA_root_replacement_required']
    assert reopen['additional_contacts'] and not reopen['base_rail_contacts']
    assert all(p['lost_volume_mm3']<1e-6 for p in reopen['pcb_post_preservation'])


def test_closed_candidate_exports_with_print_margin():
    proof=read('source-retention-reopen.json')
    assert proof['fresh_relocated_reopen'] and proof['parameter_restored']
    assert len(proof['exports'])==4
    for export in proof['exports']:
        assert export['closed'] and max(export['dimensions_mm'])<=246
        assert not export['selected'] and not export['print_ready']


def load_tests(loader, tests, pattern):
    return unittest.TestSuite(unittest.FunctionTestCase(fn) for name,fn in sorted(globals().items())
                              if name.startswith('test_') and callable(fn))


if __name__=='__main__':
    unittest.main()
